from collections import deque

def pred(a, conn=4, border=True, adj8=True):
 h,w=a.shape; pred=a.copy()
 seed=tuple(np.argwhere(a==6)[0])
 nbrs=[(-1,0),(1,0),(0,-1),(0,1)] if conn==4 else [(dr,dc) for dr in (-1,0,1) for dc in (-1,0,1) if dr or dc]
 seen={seed}; q=deque([seed])
 while q:
  r,c=q.popleft()
  for dr,dc in nbrs:
   rr,cc=r+dr,c+dc
   if 0<=rr<h and 0<=cc<w and a[rr,cc]==8 and (rr,cc) not in seen:
    seen.add((rr,cc)); q.append((rr,cc))
 contour_nbrs=[(dr,dc) for dr in (-1,0,1) for dc in (-1,0,1) if (dr or dc)] if adj8 else nbrs
 for r,c in list(seen):
  if a[r,c]!=8: continue
  boundary=border and (r==0 or c==0 or r==h-1 or c==w-1)
  for dr,dc in contour_nbrs:
   rr,cc=r+dr,c+dc
   if not (0<=rr<h and 0<=cc<w) or a[rr,cc]==1: boundary=True
  if boundary: pred[r,c]=7
 return pred
for i,(a,b) in enumerate(pairs,1):
 for conn in (4,8):
  p=pred(a,conn)
  print(i,conn,'matches',np.array_equal(p,b),'errors',np.sum(p!=b), 'extra',np.sum((p==7)&(b!=7)), 'miss',np.sum((p!=7)&(b==7)))

